import Foundation
import SkeletonCore

/// Every contract function, called by its unit's and its own name with arguments made from a vector's JSON.
enum VectorCalls {
    static func call(_ unit: String, _ function: String, _ arguments: VectorArguments) throws -> VectorJSON {
        switch unit + "." + function {
        case "TipMath.percent":
            return try VectorJSON.encoding(TipMath.percent(for: arguments.value("service")))
        case "TipMath.breakdown":
            return try VectorJSON.encoding(TipMath.breakdown(bill: arguments.value("bill"), percent: arguments.value("percent"), people: arguments.value("people")))
        case "TipMath.shares":
            return try VectorJSON.encoding(TipMath.shares(total: arguments.value("total"), people: arguments.value("people")))
        default:
            throw VectorFailure.unknownFunction(unit + "." + function)
        }
    }
}
